const D = { density:.55, energy:.6, speed:1, scale:1, hue:8, x:.5, y:.5, scan:.6, style:'mono', seed:0, alpha:100, act:'stream' };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clp=(v,a,b)=>Math.max(a,Math.min(b,v));
const md=(a,n)=>((a%n)+n)%n;
const TAU=Math.PI*2;
const nf2=n=>(n<10?'0':'')+n;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
const SEED=(P.seed|0);
function hsh(a,b){let h=(a*374761393 + b*668265263 + SEED*2654435761)|0; h=(h^(h>>13))*1274126177|0; return ((h^(h>>16))>>>0)/4294967295;}
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

const W=width,H=height,u=Math.min(W,H);
const style=P.style;
const dens=clp(P.density,0,1), en=clp(P.energy,0,1), spd=clp(P.speed,0,3.5), scl=clp(P.scale,0.4,2.4);
const scan=clp(P.scan,0,1), aM=clp(P.alpha,0,100)/100;
const hue=md(P.hue,360);
const sec=K.section|0;
const intens=clp(K.intensity,0,1);
const drive=0.32+0.68*intens;
const act=P.act;

// section-keyed salt: whole data-scape reshuffles on musical-section boundaries
const salt=sec*97 + 13;
// act dramaturgy: stream (balanced) / spectrum (bars+wave forward, barcode recedes) / glitch (tearing)
const glitchAmt = act==='glitch' ? clp((intens-0.35)*1.7,0,1) : 0;
const specBoost = act==='spectrum' ? (0.7+0.85*drive) : 1;
const codeDim   = act==='spectrum' ? 0.55 : 1;

// ---- style palette (single accent color per look) ----
let BG,INK,ACC,GRID,soft=false,split=false,hollow=false,crt=false,tickBoost=1;
if(style==='amber'){ BG=[32,62,4]; INK=[38,78,92]; ACC=[18,92,100]; GRID=[34,55,11]; soft=true; crt=true; }
else if(style==='blueprint'){ BG=[212,82,10]; INK=[196,66,90]; ACC=[26,90,100]; GRID=[205,60,24]; hollow=true; }
else if(style==='datamosh'){ BG=[0,0,4]; INK=[0,0,96]; ACC=[305,88,100]; GRID=[0,0,15]; split=true; }
else if(style==='phosphor'){ BG=[128,45,3]; INK=[125,82,90]; ACC=[92,90,100]; GRID=[128,50,11]; soft=true; crt=true; tickBoost=1.25; }
else { BG=[0,0,4]; INK=[0,0,96]; ACC=[hue,86,100]; GRID=[0,0,13]; } // mono (default anchor)

const splitBase = (split? 2.2 : 0) + glitchAmt*5.5;
const splitAmt = splitBase * u*0.0016;

// ---- register layout (deterministic from seed + nReg + H) ----
const nReg=Math.round(4+dens*5);
const REGT=['barcode','spectrum','wave','ticker','barcode','ticker','spectrum','wave'];
const rot=SEED%REGT.length;
const topPad=u*0.05, botPad=u*0.035;
const xL=u*0.065, xR=W-u*0.03, regW=xR-xL;
let wsum=0; const wts=[];
for(let r=0;r<nReg;r++){ const w=0.55+fr(r*5+1)*1.0; wts.push(w); wsum+=w; }
const availH=H-topPad-botPad;
const regs=[]; let yreg=topPad;
for(let r=0;r<nReg;r++){ const h=availH*wts[r]/wsum; regs.push({y0:yreg,y1:yreg+h,type:REGT[(r+rot)%REGT.length],id:r}); yreg+=h; }

// ---- cached chrome: bg + graph grid + register frames/labels + rulers (static, size/style/seed keyed) ----
const ckey=W+'x'+H+':'+style+':'+SEED+':'+nReg+':'+Math.round(hue);
if(!S.chrome || S.ckey!==ckey){
  if(S.chrome && S.chrome.remove) S.chrome.remove();
  const g=createGraphics(W,H); g.colorMode(HSB,360,100,100,100); g.pixelDensity(1);
  g.background(BG[0],BG[1],BG[2]);
  g.strokeWeight(1); g.stroke(GRID[0],GRID[1],GRID[2]);
  const gs=Math.max(14,u*0.052);
  for(let x=xL;x<=xR;x+=gs) g.line(x,topPad,x,H-botPad);
  for(let y=topPad;y<=H-botPad;y+=gs) g.line(xL,y,xR,y);
  g.textFont('monospace');
  for(const rg of regs){
    g.stroke(INK[0],INK[1],INK[2]*0.5,60); g.strokeWeight(1); g.noFill();
    g.line(xL,rg.y0,xR,rg.y0);
    g.noStroke(); g.fill(INK[0],INK[1],INK[2]*0.7,74);
    g.textAlign(LEFT,TOP); g.textSize(Math.max(7,u*0.013));
    const lbl=(rg.type==='barcode'?'BARCODE':rg.type==='spectrum'?'SPECTRA':rg.type==='wave'?'WAVE.OSC':'DATA.HEX')+' '+nf2(rg.id);
    g.text(lbl, xL, rg.y0+2);
  }
  g.stroke(INK[0],INK[1],INK[2]*0.5,60); g.strokeWeight(1); g.line(xL,H-botPad,xR,H-botPad);
  // rulers
  g.stroke(INK[0],INK[1],INK[2]*0.6,70);
  for(let y=topPad;y<=H-botPad;y+=gs*0.5){ const big=(Math.round((y-topPad)/(gs*0.5))%2===0); g.line(xL-u*(big?0.016:0.009), y, xL, y); }
  for(let x=xL;x<=xR;x+=gs*0.5){ const big=(Math.round((x-xL)/(gs*0.5))%2===0); g.line(x, topPad-u*(big?0.016:0.009), x, topPad); }
  // corner crop marks in accent
  g.stroke(ACC[0],ACC[1],ACC[2],72); g.strokeWeight(Math.max(1,u*0.002));
  const cm=u*0.02;
  g.line(xL,topPad,xL+cm,topPad); g.line(xL,topPad,xL,topPad+cm);
  g.line(xR,topPad,xR-cm,topPad); g.line(xR,topPad,xR,topPad+cm);
  g.line(xL,H-botPad,xL+cm,H-botPad); g.line(xL,H-botPad,xL,H-botPad-cm);
  g.line(xR,H-botPad,xR-cm,H-botPad); g.line(xR,H-botPad,xR,H-botPad-cm);
  // title strip
  g.noStroke(); g.fill(INK[0],INK[1],INK[2]*0.85,86); g.textAlign(LEFT,BOTTOM); g.textSize(Math.max(8,u*0.018));
  g.text('DATA—SCAPE', xL, topPad-u*0.006);
  g.fill(INK[0],INK[1],INK[2]*0.6,70); g.textAlign(RIGHT,BOTTOM); g.textSize(Math.max(7,u*0.013));
  g.text(style.toUpperCase()+'  '+nf2(nReg)+'CH', xR, topPad-u*0.006);
  if(crt){ g.stroke(0,0,0,26); g.strokeWeight(1); const sp=Math.max(2,u*0.005); for(let y=0;y<H;y+=sp) g.line(0,y,W,y); }
  S.chrome=g; S.ckey=ckey;
}

// ---- draw chrome (opaque at default; translucent ground when alpha<100) ----
if(P.alpha>=100){ image(S.chrome,0,0); }
else { push(); tint(0,0,100,P.alpha); image(S.chrome,0,0); pop(); }

// ---- dynamic data marks ----
let budget=2000;
let curSplit=false;
function bar(x,y,w,h,b,acc){
  if(h<=0||w<=0||budget<=0) return; budget--;
  if(curSplit){
    const o=splitAmt + (glitchAmt>0.5? (hsh(x|0,y|0)-0.5)*u*0.01*glitchAmt : 0);
    noStroke();
    fill(0,100,100,82*aM); rect(x-o,y,w,h);
    fill(120,100,100,82*aM); rect(x,y,w,h);
    fill(240,100,100,82*aM); rect(x+o,y,w,h);
    return;
  }
  if(acc){ noStroke(); fill(ACC[0],ACC[1],100,92*aM); rect(x,y,w,h); return; }
  if(hollow){ noFill(); stroke(INK[0],INK[1],b,90*aM); strokeWeight(Math.max(1,u*0.0016)); rect(x+0.5,y+0.5,w-1,h-1); noStroke(); return; }
  noStroke(); fill(INK[0],INK[1],b,(soft?88:96)*aM); rect(x,y,w,h);
}
function atick(x,y,w){ if(budget<=0)return; budget--; noStroke(); fill(ACC[0],ACC[1],100,84*aM); rect(x,y-Math.max(1,u*0.0022),w,Math.max(1.5,u*0.003)); }

for(const rg of regs){
  const ry0=rg.y0, ry1=rg.y1, ipad=Math.min((ry1-ry0)*0.18, u*0.02);
  const y0=ry0+ipad, y1=ry1-ipad, rh=y1-y0, cy=(y0+y1)/2;
  const focus=(rg.id===sec%nReg);
  const fB=focus?1.14:1.0;
  const type=rg.type;
  curSplit = split && (type==='barcode'||type==='spectrum');
  if(curSplit) blendMode(ADD);

  if(type==='barcode'){
    const bw=Math.max(2, u*0.0062*(1.7-dens*0.9)*scl);
    const nb=Math.min(230, Math.ceil(regW/bw)+1);
    const ph=K.t*(0.6+spd*1.0);
    const fpx=(ph-Math.floor(ph))*bw, base=Math.floor(ph);
    const litT=(0.64-0.36*en*drive)+(act==='spectrum'?0.14:0);
    for(let c=0;c<nb;c++){
      const idx=base+c;
      if(hsh(idx*3+7, rg.id*131+salt) < litT) continue;
      const lvl=hsh(idx*3+9, rg.id*131+salt+5);
      const b=clp((52+Math.round(lvl*3)/3*44)*fB*codeDim,0,100);
      const hh=rh*(0.4+0.6*hsh(idx*5, rg.id+salt));
      const acc=(!split && hsh(idx, sec*17)>0.94 && K.pulse>0.35);
      bar(xL + c*bw - fpx, y1-hh, bw*0.82, hh, b, acc);
    }
  } else if(type==='spectrum'){
    const nbar=Math.min(72, Math.round(14+dens*46));
    const gap=regW/nbar, bw=gap*0.6;
    S.pk=S.pk||{}; const pk=S.pk[rg.id]||(S.pk[rg.id]=new Float32Array(72));
    for(let k=0;k<nbar;k++){
      const tilt=Math.pow(1-k/nbar,0.55);
      const env=hsh(k*7+3, rg.id*57+salt);
      const wob=0.5+0.5*Math.sin(K.t*(0.7+spd*0.6)+k*0.6+env*6.0);
      const af=(A.fft&&A.fft.length)?A.fft[k%A.fft.length]:0;
      let h=(0.12+env*0.5*tilt+0.32*wob*tilt)*drive*(0.5+en)*specBoost+af*0.7*drive;
      h=clp(h,0,1);
      const steps=Math.round(6+dens*10); h=Math.round(h*steps)/steps;
      const bh=h*rh, bx=xL+k*gap+(gap-bw)/2;
      bar(bx, y1-bh, bw, bh, clp((58+h*38)*fB,0,100), false);
      if(bh>pk[k]) pk[k]=bh; else pk[k]=Math.max(bh, pk[k]-rh*0.006);
      if(!curSplit) atick(bx, y1-pk[k], bw); else { noStroke(); fill(ACC[0],ACC[1],100,84*aM); rect(bx,y1-pk[k]-u*0.002,bw,u*0.003); }
    }
  } else if(type==='wave'){
    const amp=Math.min(rh*0.46, rh*0.44*(0.4+0.6*drive+A.rms*0.8)*specBoost)*fB;
    const ns=Math.min(170, Math.round(44+regW/(u*0.02)));
    const ph=K.t*(1.2+spd*1.4);
    noFill(); stroke(INK[0],INK[1],INK[2]*(soft?0.9:1),90*aM); strokeWeight(Math.max(1,u*0.0024*scl));
    beginShape();
    for(let s=0;s<=ns;s++){ const xx=s/ns;
      const w=Math.sin(xx*TAU*3+ph)*0.6+Math.sin(xx*TAU*7-ph*1.3+hsh(rg.id,1)*6)*0.28+Math.sin(xx*TAU*13+ph*0.7)*0.12*(A.mid+0.3);
      vertex(xL+xx*regW, cy-w*amp);
    }
    endShape();
    const cxx=((K.t*(0.13+spd*0.1))%1);
    const cw=Math.sin(cxx*TAU*3+ph)*0.6+Math.sin(cxx*TAU*7-ph*1.3+hsh(rg.id,1)*6)*0.28;
    const cx=xL+cxx*regW, cyy=cy-cw*amp;
    noStroke(); if(soft){drawingContext.shadowBlur=12;drawingContext.shadowColor='rgba(255,255,255,0.7)';}
    fill(ACC[0],ACC[1],100,95*aM); circle(cx,cyy,Math.max(3,u*0.006)); drawingContext.shadowBlur=0;
    stroke(INK[0],INK[1],INK[2]*0.4,40*aM); strokeWeight(1); line(xL,cy,xR,cy);
  } else { // ticker (hex data columns)
    const cw=Math.max(u*0.013, u*0.02*scl*(1.45-0.7*dens));
    const ch=cw*1.12;
    const ncol=Math.min(64, Math.floor(regW/cw));
    const nrow=Math.max(1, Math.min(6, Math.floor(rh/ch)));
    const rate=Math.floor(K.t*(2+spd*3));
    const GLY="0123456789ABCDEF";
    textFont('monospace'); textAlign(CENTER,CENTER); textSize(ch*0.78); noStroke();
    for(let r2=0;r2<nrow && budget>0;r2++) for(let c=0;c<ncol && budget>0;c++){
      if(hsh(c*13+r2*29, rg.id*3)<0.36) continue; budget--;
      const fast=hsh(c*3+r2, rg.id)>0.78;
      const v=hsh(c*7+r2*5+rg.id, fast? rate*2 : rate+sec);
      const b=clp((38+Math.round(hsh(c+r2*7,rate)*3)/3*54)*fB*tickBoost,0,100);
      fill(INK[0],INK[1],b,88*aM);
      text(GLY[(v*16|0)&15], xL+(c+0.5)*cw, y0+(r2+0.5)*ch);
    }
  }
  if(curSplit) blendMode(BLEND);
}
curSplit=false;

// ---- global scanning sine-grid overlay (ties registers; continuous drift) ----
noFill(); stroke(ACC[0],ACC[1]*0.85,100,(24+34*scan)*aM); strokeWeight(Math.max(1,u*0.0016));
const gph=K.t*(0.5+spd*0.6);
beginShape();
for(let s=0;s<=120;s++){ const xx=s/120; const yv=0.5+0.33*Math.sin(xx*TAU*2+gph)*Math.sin(gph*0.3+xx*3.0); vertex(xL+xx*regW, topPad+(H-topPad-botPad)*yv); }
endShape();

// ---- vertical scan sweep = MOTION FLOOR (pure K.t, never rephases) ----
const scanX=xL+((K.t*(0.05+spd*0.06))%1)*regW;
push(); blendMode(ADD); noStroke();
const sw=u*(0.008+0.05*scan);
for(let i=5;i>=1;i--){ fill(ACC[0],ACC[1]*0.5,100,(5+7*scan)*(i/5)*aM); rect(scanX-sw*i*0.5,0,sw*i,H); }
fill(0,0,100,(38+42*scan)*aM); rect(scanX-Math.max(1,u*0.0016),0,Math.max(2,u*0.0034),H);
blendMode(BLEND); pop();

// ---- horizontal secondary scan (slower, faint cross motion) ----
const scanY=topPad+((K.t*(0.021+spd*0.02))%1)*(H-topPad-botPad);
push(); blendMode(ADD); noStroke();
fill(ACC[0],ACC[1]*0.45,100,(7+8*scan)*aM); rect(0,scanY-u*0.006,W,u*0.012);
blendMode(BLEND); pop();

// ---- measurement reticle at (x,y) — honors universal anchor as a data cursor ----
const rx=xL+clp(P.x,0,1)*regW, rry=topPad+clp(P.y,0,1)*(H-topPad-botPad);
const rr=u*(0.03+0.012*Math.sin(K.t*0.9));
push(); noFill(); stroke(ACC[0],ACC[1],100,70*aM); strokeWeight(Math.max(1,u*0.0018));
line(rx-rr,rry,rx-rr*0.35,rry); line(rx+rr*0.35,rry,rx+rr,rry);
line(rx,rry-rr,rx,rry-rr*0.35); line(rx,rry+rr*0.35,rx,rry+rr);
rectMode(CENTER); rect(rx,rry,rr*0.9,rr*0.9); rectMode(CORNER);
noStroke(); fill(ACC[0],ACC[1],100,80*aM); textFont('monospace'); textAlign(LEFT,BOTTOM); textSize(Math.max(7,u*0.012));
text('X'+clp(P.x,0,1).toFixed(2)+' Y'+clp(P.y,0,1).toFixed(2), rx+rr*0.55, rry-rr*0.4);
pop();

// ---- HUD telemetry (reads as reacting to the musical arc) ----
noStroke(); textFont('monospace'); textAlign(LEFT,TOP); textSize(Math.max(8,u*0.016));
fill(INK[0],INK[1],INK[2]*0.75,72*aM);
text('SEC '+nf2(sec)+'  INT '+intens.toFixed(2)+'  T'+K.t.toFixed(1)+'  '+act.toUpperCase(), xL, H-botPad+u*0.006);

// ---- beat blink marker (partial corner, never full-frame) ----
if(K.pulse>0.5){ noStroke(); fill(ACC[0],ACC[1],100,72*K.pulse*aM); const bs=u*0.028; rect(xR-bs,topPad*0.4,bs,bs); }

blendMode(BLEND); drawingContext.shadowBlur=0; rectMode(CORNER); textAlign(LEFT,BASELINE);
